#!/usr/bin/env python3
# SPDX-License-Identifier: MIT
"""Trim generated lines and make direct-play S16 assets without runtime decoding."""
from pathlib import Path
import argparse, hashlib, json, shutil, subprocess
import numpy as np

app=Path(__file__).resolve().parents[1]
p=argparse.ArgumentParser();p.add_argument('--source',type=Path,required=True);p.add_argument('--report',type=Path,required=True);args=p.parse_args()
config_path=Path(__file__).with_name('voice-prompts.json');config=json.loads(config_path.read_text())
runtime=app/'assets/audio/voices';masters=app/'art/audio/voices';runtime.mkdir(parents=True,exist_ok=True);masters.mkdir(parents=True,exist_ok=True)
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def decode(p):return np.frombuffer(subprocess.check_output(['ffmpeg','-v','error','-i',str(p),'-ac','1','-ar','16000','-af','highpass=f=140,lowpass=f=6400','-f','f32le','-']),dtype='<f4').copy()
report={};files=[None]*40;lengths=[0]*40
for c in config['cast']:
 ref=args.source/(c['id']+'-reference.flac');shutil.copyfile(ref,masters/ref.name);c['reference_sha256']=sha(ref)
 for cue,text in c['lines'].items():
  name=c['id']+'-'+cue;source=args.source/(name+'.flac');a=decode(source)
  # A conservative 10ms envelope keeps quiet consonants and breath attacks.
  frames=len(a)//160;env=np.sqrt(np.mean(a[:frames*160].reshape(-1,160)**2,axis=1));active=np.flatnonzero(env>max(.0015,float(env.max())*.035));assert len(active),name
  start=max(0,int(active[0])*160-640);end=min(len(a),(int(active[-1])+1)*160+1280);a=a[start:end];a-=a.mean()
  rms=float(np.sqrt(np.mean(a*a)));a*=min(.76/max(abs(a)),.17/max(1e-9,rms));fade=min(80,len(a)//4);a[:fade]*=np.linspace(0,1,fade);a[-fade:]*=np.linspace(1,0,fade)
  assert .3<len(a)/16000<4.5,(name,len(a)/16000)
  pcm=np.clip(np.rint(a*32767),-32768,32767).astype('<i2');dst=runtime/(name+'.s16');dst.write_bytes(pcm.tobytes());master=masters/(name+'.flac')
  subprocess.run(['ffmpeg','-v','error','-y','-f','s16le','-ar','16000','-ac','1','-i',str(dst),'-c:a','flac',str(master)],check=True)
  slot={'select_0':0,'select_1':1,'move_0':2,'move_1':3,'attack_0':4,'attack_1':5,'stop':6,'ready':7}[cue];index=c['kind']*8+slot;files[index]=name;lengths[index]=(len(a)*1000+15999)//16000
  report[name]={'text':text,'duration':len(a)/16000,'peak':float(abs(pcm.astype(float)).max()/32768),'rms':float(np.sqrt(np.mean((pcm.astype(float)/32768)**2))),'trim_start':start/16000,'trim_end':end/16000,'source_sha256':sha(source),'master_sha256':sha(master),'runtime_sha256':sha(dst),'runtime_bytes':dst.stat().st_size}
  print(name,round(len(a)/16000,2),flush=True)
header='// SPDX-License-Identifier: MIT\n// Generated by tools/prepare_voices.py.\n#pragma once\n#include <cstdint>\nnamespace iron {\ninline constexpr const char* voice_files[]={\n'+''.join((' "'+f+'",\n') if f else ' nullptr,\n' for f in files)+'};\ninline constexpr uint16_t voice_lengths[]={'+','.join(map(str,lengths))+'};\n}\n'
(app/'voice_data.hpp').write_text(header)
config['model_sha256']=json.loads((args.source/'model-hashes.json').read_text())
config['processing']={'sample_rate':16000,'channels':1,'encoding':'S16LE','highpass_hz':140,'lowpass_hz':6400,'peak_limit':.76,'target_rms':.17,'lines':{k:{field:v[field] for field in ('duration','trim_start','trim_end','source_sha256','master_sha256','runtime_sha256','runtime_bytes')} for k,v in report.items()}}
config_path.write_text(json.dumps(config,ensure_ascii=False,indent=2)+'\n');args.report.write_text(json.dumps(report,ensure_ascii=False,indent=2)+'\n')
print('Voice runtime bytes',sum(x['runtime_bytes'] for x in report.values()))
